  const tf = [
    {s:14, st:"Die neoplastischen Zellen der Langerhans-Zell-Histiozytose stammen von epidermalen Langerhans-Zellen ab.", c:false, e:"Falsch - sie stammen von myeloischen dendritischen Vorläuferzellen ab, nicht von den epidermalen Langerhans-Zellen."},
    {s:14, st:"CD207 (Langerin) ist der Marker für Birbeck-Granula und damit spezifisch für Langerhans-Zellen.", c:true, e:"Korrekt - Langerin/CD207 markiert Birbeck-Granula; zusammen mit CD1a und S100 bildet es die Langerhans-Zell-Trias."},
    {s:14, st:"Bei der LCH ist eine Assoziation mit anderen Malignomen bei Erwachsenen deutlich häufiger als bei Kindern.", c:true, e:"Korrekt - Kinder ca. 3%, Erwachsene ca. 33% (Lungen-/Schilddrüsenkarzinom, Leukämien, Lymphome, therapiebedingte Tumoren)."},
    {s:14, st:"Eine unifokale LCH der Schädelbasis mit intrakranieller Ausbreitung wird als 'special site' auch bei Single-system-Erkrankung systemisch therapiert.", c:true, e:"Korrekt - Schädelbasis- und Wirbelsäulenläsionen mit intrakranieller bzw. intraspinaler Ausbreitung sind 'special sites' mit Therapieindikation."},
    {s:14, st:"Die Histiozyten der Erdheim-Chester-Erkrankung sind CD1a- und CD207-positiv.", c:false, e:"Falsch - ECD-Histiozyten sind CD68+/CD163+, aber CD1a- und CD207-negativ; die L-Gruppen-Zuordnung beruht auf der gemeinsamen MAPK-Mutation."},
    {s:14, st:"Die Herzbeteiligung ist bei der Erdheim-Chester-Erkrankung eine häufige Todesursache.", c:true, e:"Korrekt - Klappenvitien, Gefässfibrosierung und Herzrhythmusstörungen sind bei der ECD eine häufige Todesursache; ca. 50% der Verläufe sind letal."},
    {s:14, st:"Die Rosai-Dorfman-Erkrankung verläuft meist indolent und selbstlimitierend.", c:true, e:"Korrekt - häufig indolent oder selbstlimitierend, kann aber protrahiert mit Exazerbationen und Remissionen verlaufen; ggf. Clofarabin."},
    {s:14, st:"Das juvenile Xanthogranulom ist immer CD1a- und CD207-negativ.", c:true, e:"Korrekt - JXG-Histiozyten sind CD68+/CD163+, manchmal S100+, aber immer CD1a- und CD207-negativ (Abgrenzung zur LCH)."},
    {s:14, st:"Die benigne zephale Histiozytose erfordert keinerlei Verlaufskontrolle, da sie immer folgenlos abheilt.", c:false, e:"Falsch - trotz selbstlimitierendem Verlauf ist ein regelmässiges Screening empfohlen, da ein erhöhtes Risiko für Transformation in eine LCH beschrieben ist."},
    {s:14, st:"Beim nekrobiotischen Xanthogranulom ist die periorbitale Region die Prädilektionsstelle.", c:true, e:"Korrekt - periorbital >>> Stirn, Stamm und Extremitätenstreckseiten; dazu okuläre Beteiligung und in ca. 80% monoklonale Gammopathie."},
    {s:14, st:"Eruptive Xanthome sprechen typischerweise langsam über Jahre auf die Lipidtherapie an.", c:false, e:"Falsch - eruptive Xanthome sprechen rasch auf Fenofibrat und die Behandlung der Grunderkrankung an; tuberöse Xanthome dagegen langsam auf Statine/PCSK9-Inhibitoren."},
    {s:14, st:"Xanthelasmen schliessen eine normale Lipidkonstellation aus.", c:false, e:"Falsch - Xanthelasmen treten bei Hyperlipidämie Typ II/III auf, kommen aber auch normolipämisch vor; plane Xanthome bei Normolipämie weisen auf eine monoklonale Gammopathie hin."},
    {s:14, st:"Das verruköse Xanthom ist typischerweise mit einer Hypertriglyzeridämie assoziiert.", c:false, e:"Falsch - das verruköse Xanthom hat keinen Zusammenhang mit Hyperlipidämien (idiopathisch, RDEB, CHILD-Syndrom, Lymphödem, GvHD, oraler Lichen planus)."},
    {s:14, st:"Sarkoidale Granulome zeigen typischerweise eine zentrale Verkäsung.", c:false, e:"Falsch - Sarkoidose-Granulome sind nicht verkäsend und 'nackt' (ohne nennenswerten Lymphozytensaum); Verkäsung spricht für Tuberkulose."},
    {s:14, st:"Das Erythema nodosum ist die häufigste unspezifische Hautmanifestation der Sarkoidose.", c:true, e:"Korrekt - das EN (septale Pannikulitis ohne Vaskulitis) ist die häufigste unspezifische Läsion, z.B. im Rahmen des Löfgren-Syndroms."},
    {s:14, st:"In der bronchoalveolären Lavage ist bei Sarkoidose der CD4/CD8-Quotient erniedrigt.", c:false, e:"Falsch - der CD4/CD8-Quotient in der BAL ist bei Sarkoidose erhöht (T-Helferzell-dominierte Th1-Antwort)."},
    {s:14, st:"Das lokalisierte Granuloma anulare heilt in etwa 50% innerhalb von 2 Jahren spontan ab, rezidiviert aber in ca. 40%.", c:true, e:"Korrekt - lokalisiertes GA ist selbstlimitierend (50% in 2 Jahren) mit Rezidivrate um 40%; generalisiertes GA verläuft chronisch."},
    {s:14, st:"Bei der Necrobiosis lipoidica ist die Schmerz- und Berührungsempfindung in den Plaques typischerweise vermindert.", c:true, e:"Korrekt - Hypästhesie, Hypohidrose und Haarverlust in den Plaques sind typisch; Ulzeration nach Trauma möglich."},
    {s:14, st:"Sarcoid-like Reaktionen können durch Checkpoint-Inhibitoren und TNF-alpha-Inhibitoren ausgelöst werden.", c:true, e:"Korrekt - medikamentös induzierte sarcoid-like Reaktionen sind unter Checkpoint-Inhibitoren, TNF-alpha-Inhibitoren und nach COVID-Impfung beschrieben."}
  ];
